<?php
require_once __DIR__ . '/includes/auth.php'; require_staff();$pdo=db();$format=$_GET['format']??'csv';$rows=$pdo->query('SELECT case_no,report_type,incident_type,complainant,respondent,location,status,priority,incident_date FROM blotters ORDER BY incident_date DESC')->fetchAll();$stats=$pdo->query('SELECT report_type,COUNT(*) total FROM blotters GROUP BY report_type ORDER BY total DESC')->fetchAll();$title='Barangay Report Register and Analytics';$generated=date('F d, Y h:i A');$signatory='Hon. Roberto Reyes, Punong Barangay';
if($format==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="barangay-report-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,[$title]);fputcsv($out,['Generated',$generated]);fputcsv($out,['Designated signatory',$signatory]);fputcsv($out,[]);fputcsv($out,['Case No.','Report Type','Incident','Complainant','Respondent','Location','Status','Priority','Incident Date']);foreach($rows as $row)fputcsv($out,$row);fputcsv($out,[]);fputcsv($out,['Analytics by report type']);fputcsv($out,['Report Type','Count']);foreach($stats as $stat)fputcsv($out,[$stat['report_type'],$stat['total']]);fclose($out);exit;}
if($format==='word'){header('Content-Type:application/msword');header('Content-Disposition:attachment; filename="barangay-report-'.date('Y-m-d').'.doc"');echo '<html><meta charset="utf-8"><body><h1>'.h($title).'</h1><p>Generated: '.h($generated).'<br>Designated signatory: '.h($signatory).'</p><h2>Analytics by report type</h2><table border="1" cellpadding="5"><tr><th>Report type</th><th>Count</th></tr>';foreach($stats as $stat)echo '<tr><td>'.h($stat['report_type']).'</td><td>'.h($stat['total']).'</td></tr>';echo '</table><h2>Itemized report register</h2><table border="1" cellpadding="5"><tr><th>Case</th><th>Type</th><th>Incident</th><th>Complainant</th><th>Location</th><th>Status</th></tr>';foreach($rows as $row)echo '<tr><td>'.h($row['case_no']).'</td><td>'.h($row['report_type']).'</td><td>'.h($row['incident_type']).'</td><td>'.h($row['complainant']).'</td><td>'.h($row['location']).'</td><td>'.h($row['status']).'</td></tr>';echo '</table><br><br><p>Prepared by: '.h(current_user()['full_name']).'</p><p>_____________________________<br>'.h($signatory).'</p></body></html>';exit;}
function simple_pdf(array $lines): string {$objects=[];$objects[]='<< /Type /Catalog /Pages 2 0 R >>';$objects[]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';$objects[]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>';$stream="BT\n/F1 10 Tf\n50 750 Td\n";foreach($lines as $line){$safe=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],mb_substr($line,0,105));$stream.='('.$safe.') Tj 0 -15 Td\n';}$stream.='ET';$objects[]='<< /Length '.strlen($stream).' >>\nstream\n'.$stream.'\nendstream';$objects[]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';$pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $i=>$object){$offsets[] = strlen($pdf);$pdf.=($i+1).' 0 obj\n'.$object.'\nendobj\n';}$xref=strlen($pdf);$pdf.='xref\n0 '.(count($objects)+1).'\n0000000000 65535 f \n';for($i=1;$i<=count($objects);$i++)$pdf.=str_pad((string)$offsets[$i],10,'0',STR_PAD_LEFT).' 00000 n \n';$pdf.='trailer\n<< /Size '.(count($objects)+1).' /Root 1 0 R >>\nstartxref\n'.$xref.'\n%%EOF';return $pdf;}
$lines=[$title,'Generated: '.$generated,'Designated signatory: '.$signatory,'','ANALYTICS BY REPORT TYPE'];foreach($stats as $stat)$lines[]=$stat['report_type'].': '.$stat['total'];$lines[]='';$lines[]='ITEMIZED REPORT REGISTER';foreach($rows as $row)$lines[]=$row['case_no'].' | '.$row['report_type'].' | '.$row['incident_type'].' | '.$row['complainant'].' | '.$row['status'];$lines[]='';$lines[]='Prepared by: '.current_user()['full_name'];$lines[]='Signature: __________________________';header('Content-Type:application/pdf');header('Content-Disposition:attachment; filename="barangay-report-'.date('Y-m-d').'.pdf"');echo simple_pdf($lines);exit;
